mapper.select:
with t1 as (select a.* , a.primary_key as primaryKeyValue, c.report_main_id as batch_no from ${repairTable} a LEFT JOIN ( select DISTINCT report_main_id from ${reportTable} where scrap_flag is null or scrap_flag != true ) c on c.report_main_id = a.report_main_id where a.enterprise_code = #{enterpriseCode} and a.delete_flag = false
and a.product_or_part_name like concat('%',#{data.name}, '%')
and a.buss_number like concat('%',#{data.bussNumber}, '%')
and a.status = #{data.status}
AND a.operator_user_code IN
#{userCode}
AND exists ( select 1 from ${dispatcherTable} b where b.operator_user_code=#{data.repairUserCode} and b.repair_main_id = a.primary_key)
and ${dynamicTableNameProxy.getXiHangPartQuery("a.product_or_part_code","xihang",data.partUnityNo)}
and ${dynamicTableNameProxy.getProductPartSearchObj("a.product_or_part_code",data.searchName)}
order by a.create_time desc ) select * from( select t1.* ,a.create_time as inspectTime ,a.un_passed_remark from t1 ,${inspectIntoReportTable} a where t1.report_main_id = a.primary_key and t1.inspect_origin_type = 3 union ALL select t1.* ,a.create_time as inspectTime ,a.un_passed_remark from t1 ,${inspectProcessReportTable} a where t1.report_main_id = a.primary_key and t1.inspect_origin_type = 1 union ALL select t1.* ,a.create_time as inspectTime ,a.un_passed_remark from t1 ,${inspectFinishReportTable} a where t1.report_main_id = a.primary_key and t1.inspect_origin_type = 2 ) tt order by tt.create_time desc

with t2 as( with t as( select repair_main_id, sum(submit_total_num) as submit_total_num from ${submitTable} where submit_user_code = #{data.repairUserCode} GROUP BY repair_main_id ), t1 as( select sum(un_passed_num) as un_passed_num ,repair_main_id from ${reportTable} where submit_user_code = #{data.repairUserCode} and un_passed_deal = 5 GROUP BY repair_main_id ) select a.primary_key as primaryKeyValue, c.report_main_id as batch_no, a.contract_code, a.buss_number, a.main_id, a.create_time, a.report_main_id, a.produce_Main_Id, a.inspect_origin_type, a.inspect_origin_name, a.product_or_part_code, a.product_or_part_name, a.model, a.pcs_name, a.repair_num, a.check_item, b.remark, a.operator_user_code, a.inspect_user_code, a.report_file, b.status, b.assign_num as repairNum, (b.assign_num - COALESCE(t.submit_total_num,0) + COALESCE(t1.un_passed_num,0)) as awaitInspectNum, b.finish_date from ${repairTable} a left join ${dispatcherTable} b on a.primary_key = b.repair_main_id LEFT JOIN ( select DISTINCT report_main_id,submit_user_code from ${reportTable} where scrap_flag is null or scrap_flag != true ) c on c.report_main_id = b.report_main_id and c.submit_user_code = b.operator_user_code LEFT JOIN t on a.primary_key = t.repair_main_id LEFT JOIN t1 on a.primary_key = t1.repair_main_id where a.enterprise_code = #{enterpriseCode} and b.operator_user_code=#{data.repairUserCode} and a.delete_flag = false
and a.product_or_part_name like concat('%',#{data.name}, '%')
and a.buss_number like concat('%',#{data.bussNumber}, '%')
and b.status = #{data.status}
AND a.operator_user_code IN
#{userCode}
and ${dynamicTableNameProxy.getXiHangPartQuery("a.product_Or_Part_Code","xihang",data.partUnityNo)}
and ${dynamicTableNameProxy.getProductPartSearchObj("a.product_or_part_code",data.searchName)}
order by a.create_time desc ) select * from( select t2.* ,a.create_time as inspectTime from t2 ,${inspectIntoReportTable} a where t2.report_main_id = a.primary_key and t2.inspect_origin_type = 3 union ALL select t2.* ,a.create_time as inspectTime from t2 ,${inspectProcessReportTable} a where t2.report_main_id = a.primary_key and t2.inspect_origin_type = 1 union ALL select t2.* ,a.create_time as inspectTime from t2 ,${inspectFinishReportTable} a where t2.report_main_id = a.primary_key and t2.inspect_origin_type = 2 ) tt order by tt.create_time desc

