mapper.select:
select a.*, a.primary_key as primaryKeyValue
from ${repairTable} a
where report_main_id = #{reportMainId}
  and enterprise_code = #{enterpriseCode}

with t as (select COALESCE(sum(submit_total_num), 0) as submit_total_num
           from ${submitTable}
           where submit_user_code = #{repairUserCode}
             and report_main_id = #{reportMainId}),
     t1 as (select COALESCE(sum(un_passed_num), 0) as un_passed_num
            from ${reportTable}
            where submit_user_code = #{repairUserCode}
              and report_main_id = #{reportMainId}
              and un_passed_deal = 5)

select a.assign_num,
       t.submit_total_num,
       t1.un_passed_num,
       (a.assign_num - t.submit_total_num + t1.un_passed_num) as awaitInspectNum
from ${dispatcherTable} a,
     t,
     t1
where a.operator_user_code = #{repairUserCode}
  and a.report_main_id = #{reportMainId}
  and a.enterprise_code = #{enterpriseCode}
  and a.delete_flag = false
